# CFA vs ESEM. Options, results and panel: jamovi/esemCfa.*.yaml (generated by
# tools/gen_yaml.py); jmvtools generates R/esemCfa.h.R. The statistics are in
# esemWiz() (R/engine-esem.R). Lifecycle as in R/jmv-invariance.R; .init()
# adds one ESEM loading column per factor.

esemCfaClass <- if (requireNamespace("jmvcore", quietly = TRUE)) R6::R6Class(
  "esemCfaClass",
  inherit = esemCfaBase,
  private = list(
    .init = function() {
      factors <- psw_jmv_factors(self$options$factors)
      for (k in seq_along(factors))
        self$results$loadings$addColumn(name = paste0("e", k), title = names(factors)[k],
                                        superTitle = "ESEM", type = "number", format = "zto")
    },
    .run = function() {
      opt <- self$options
      out <- self$results
      factors <- psw_jmv_factors(opt$factors)
      if (length(factors) < 2L || !psw_jmv_ready(factors)) {
        psw_jmv_todo(out$todo, c(
          "Drag the items of each factor into its box. ESEM needs at least two factors with two or more items each.",
          "Then tick <b>Run analysis</b>. Nothing is fitted before that, so you can set every option first."))
        return(invisible())
      }
      res <- out$fit$state
      if (is.null(res)) {
        if (!opt$run) {
          prep <- tryCatch(psw_prepare(self$data, factors, type = opt$type),
                           error = function(e) jmvcore::reject(conditionMessage(e), code = ""))
          psw_jmv_todo(out$todo, c(
            sprintf("Ready: %d factors, %d items treated as <b>%s</b>, N = %d. A CFA and an ESEM (%s rotation) will be fitted.",
                    length(factors), length(unlist(factors)), prep$type, nrow(prep$data), opt$rotation),
            "Tick <b>Run analysis</b> to fit them."), prep$notes)
          return(invisible())
        }
        res <- tryCatch(
          esemWiz(self$data, factors, type = opt$type, estimator = opt$estimator, missing = opt$missing,
                  rotation = opt$rotation, parallel = if (opt$parallel) "auto" else FALSE),
          error = function(e) jmvcore::reject(conditionMessage(e), code = ""))
        out$fit$setState(res)
      }
      psw_jmv_todo(out$todo)
      info <- res$info

      rows <- psw_jmv_fit_rows(res$fit)
      for (i in seq_along(rows)) rows[[i]]$chisqStd <- res$fit$chisq.std[i]
      psw_jmv_fill(out$fit, rows)
      out$fit$setNote("info", sprintf(
        "CFA: each item loads on its own factor only. ESEM: every item may load on every factor. Estimator: %s; items treated as %s; missing values: %s. %s %s",
        info$estimator, info$type, info$missing, paste0(psw_jmv_variant_text(info$variant), ""),
        psw_jmv_time_text(info)), init = FALSE)
      psw_jmv_notes(out$fit, res$notes)

      cp <- res$comparison
      psw_jmv_fill(out$comparison, list(list(dchisq = cp$dchisq[1L], ddf = cp$ddf[1L], p = cp$p[1L],
                                              dcfi = cp$dcfi[1L], drmsea = cp$drmsea[1L], dsrmr = cp$dsrmr[1L])))
      out$comparison$setNote("what", paste0(
        "CFA minus ESEM. The CFA is the ESEM with all cross-loadings fixed to zero, so a clearly worse fit means ",
        "the zero cross-loadings are too strict, and the CFA factor correlations are then likely inflated.",
        if (isTRUE(info$reversed)) " \u0394CFI and \u0394RMSEA are not interpretable here: see the note under Model Fit." else ""),
        init = FALSE)

      if (opt$showLoadings) {
        L <- res$loadings
        fn <- names(info$factors)
        items <- unique(L[c("item", "own")])
        rows <- lapply(seq_len(nrow(items)), function(i) {
          d <- L[L$item == items$item[i], , drop = FALSE]
          row <- list(own = items$own[i], item = items$item[i], cfa = d$cfa[d$target][1L])
          for (k in seq_along(fn)) row[[paste0("e", k)]] <- d$esem[d$factor == fn[k]][1L]
          row
        })
        psw_jmv_fill(out$loadings, rows)
        if (opt$highlight) for (i in seq_len(nrow(items))) for (k in seq_along(fn)) {
          v <- rows[[i]][[paste0("e", k)]]
          own <- fn[k] == items$own[i]
          if (isTRUE(if (own) abs(v) < 0.40 else abs(v) >= 0.30))
            out$loadings$addFormat(rowNo = i, col = paste0("e", k), format = jmvcore::Cell.NEGATIVE)
        }
        out$loadings$setNote("what", paste0(
          "Standardized loadings. In the ESEM columns, values outside an item's own factor are cross-loadings.",
          if (opt$highlight) " In red: cross-loadings of .30 or more, and own-factor loadings below .40." else ""),
          init = FALSE)
      }

      if (opt$showCors) {
        cc <- res$correlations
        psw_jmv_fill(out$cors, lapply(seq_len(nrow(cc)), function(i) as.list(cc[i, , drop = FALSE])))
        out$cors$setNote("what", paste0(
          "The same correlation under different ways of scoring. Composite scores: means of the items, attenuated ",
          "by unreliability. Corrected composites: divided by the square root of the product of the two alphas. ",
          "CFA and ESEM: correlations between the latent factors. Factor scores: correlations between scores ",
          "estimated from the CFA; regression scores of correlated factors are typically too strongly correlated, ",
          "Bartlett scores (continuous items only) too weakly."), init = FALSE)
      }
      if (opt$showLoom && !is.null(res$uniqueness))
        psw_jmv_plot(out$loom, "loom", list(L = res$loadings, unique = res$uniqueness, value = "esem"))
      invisible()
    },
    .diagram = function(image, ...) psw_jmv_diagram(image)
  )
)
